const makeDefaults=()=>({
  items:[
    {id:'i1',name:'Løpevest, syntetisk eksempel',sku:'DEMO-VEST-01',category:'Bekledning',unit:'stk',qty:24,cost:490,value:390,location:'Hovedlager',status:'Tilgjengelig',runs:['Vårsamling (eksempel)'],note:'Syntetisk instruks: kontroller glidelås før bruk.',size:'M/L',weight:180,meta:{farge:'Grønn'},rentedQty:0},
    {id:'i2',name:'Førstehjelpssett, syntetisk eksempel',sku:'DEMO-SIK-02',category:'Sikkerhet',unit:'sett',qty:8,cost:650,value:520,location:'Bod A',status:'Tilgjengelig',runs:['Vårsamling (eksempel)'],note:'Syntetisk instruks: påfyll før arrangement.',size:'',weight:0,meta:{},rentedQty:0},
    {id:'i3',name:'Målportal, syntetisk eksempel',sku:'DEMO-START-03',category:'Start/mål',unit:'stk',qty:2,cost:2800,value:2100,location:'Tilhenger',status:'Reservert (til løp)',runs:['Vårsamling (eksempel)'],note:'',size:'',weight:12000,meta:{},rentedQty:0}
  ],
  instances:[{id:'u1',itemId:'i3',serial:'DEMO-ENHET-01',status:'Tilgjengelig',location:'Tilhenger',condition:'Syntetisk eksempel · uten skade'}],
  categories:['Bekledning','Sikkerhet','Start/mål','Diverse'],locations:['Hovedlager','Bod A','Tilhenger'],statuses:['Tilgjengelig','Utleid / utlånt','Reservert (til løp)','Skal selges','Defekt','Kassert'],runs:['Vårsamling (eksempel)'],attachmentCategories:['Bruksanvisning','Kvittering','Sertifikat','Annet'],metaFields:[{key:'farge',label:'Farge',type:'Tekst',unit:'',active:true,order:1},{key:'volum',label:'Volum',type:'Tall',unit:'liter',active:false,order:2}],
  attachments:[{id:'a1',itemId:'i3',label:'Syntetisk eksempel · monteringsveiledning.pdf',category:'Bruksanvisning'}],notes:[{id:'n1',itemId:'i1',text:'Syntetisk eksempelnotat: vasket og kontrollert.',date:'2026-10-01'}],
  contacts:[{id:'c1',name:'Demoarrangør (syntetisk)',org_number:'SYN-0001',email:'utleie@example.invalid',phone:'000 00 000',address:'Syntetisk eksempeladresse',note:'Fiktiv leietaker'}],contactNotes:[],
  rentals:[{id:'r1',contactId:'c1',status:'Kladd',start:'2026-10-20',end:'2026-10-22',rate:50,lines:[{itemId:'i1',qty:2,instanceIds:[]}],note:''}],
  configDone:true,shares:[],shareFilters:{category:'Alle kategorier',status:'Alle statuser'}
});
let db=makeDefaults(),currentTab='varer',itemQuery='',detailId=null,unitDetailId=null,layout='table',groupBy='none',rentalSub='leietakere',rentalStatus='',rentalDetailId=null,wizard=null,reportSub='oversikt',contactDetailId=null,notice='';
const view=document.querySelector('#view'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,money=n=>new Intl.NumberFormat('nb-NO',{style:'currency',currency:'NOK',maximumFractionDigits:0}).format(Number(n)||0),today=()=>new Date().toISOString().slice(0,10);
function log(itemId,text,instanceId=null){db.notes.push({id:id(),itemId,instanceId,text:`Historikk · ${text}`,date:today(),author:'Demo-bruker (syntetisk)',kind:'audit'})}
function opts(values,selected){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function field(name,label,value='',type='text',extra={}){const req=extra.required?'required':'',placeholder=extra.placeholder?`placeholder="${esc(extra.placeholder)}"`:'';if(type==='select')return `<label>${esc(label)}<select name="${esc(name)}" ${req}>${opts(extra.options||[],value)}</select></label>`;if(type==='textarea')return `<label>${esc(label)}<textarea name="${esc(name)}" rows="3" ${req} ${placeholder}>${esc(value)}</textarea></label>`;return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${req} ${placeholder} ${extra.min!==undefined?`min="${extra.min}"`:''} ${extra.step?`step="${extra.step}"`:''}></label>`}
function openEditor(title,fields,save,submitLabel='Lagre i denne fanen'){const d=document.querySelector('#editor-dialog'),f=document.querySelector('#editor-form');document.querySelector('#editor-title').textContent=title;document.querySelector('#editor-fields').innerHTML=fields.join('');document.querySelector('#editor-submit').textContent=submitLabel;f._demoSave=save;d.showModal()}
function closeEditor(){document.querySelector('#editor-dialog').close()}
document.querySelector('[data-close-editor]').addEventListener('click',closeEditor);
function availableQty(item){return Math.max(0,item.qty-item.rentedQty)}
function activeRentals(){return db.rentals.filter(r=>r.status==='Aktiv')}
function getItem(itemId){return db.items.find(x=>x.id===itemId)}
function itemHasOpenRental(itemId){return db.rentals.some(r=>r.status!=='Returnert'&&r.lines.some(line=>line.itemId===itemId))}
function removeItemData(itemId){db.items=db.items.filter(i=>i.id!==itemId);db.instances=db.instances.filter(u=>u.itemId!==itemId);db.attachments=db.attachments.filter(a=>a.itemId!==itemId);db.notes=db.notes.filter(n=>n.itemId!==itemId);db.rentals.forEach(r=>r.lines=r.lines.filter(line=>line.itemId!==itemId));if(detailId===itemId)detailId=null}
function categoryFilter(item){return !document.querySelector('#filter-category')||document.querySelector('#filter-category').value==='Alle kategorier'||item.category===document.querySelector('#filter-category').value}
function tableRows(items){return `<div class="table-wrap"><table><thead><tr><th>Navn</th><th>Kategori</th><th>Status</th><th>Plassering</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><a href="#item-${x.id}" data-action="detail" data-id="${x.id}">${esc(x.name)}</a>${x.sku?`<br><small>${esc(x.sku)}</small>`:''}${String(x.qty)!==''?`<br><small>${x.qty} ${esc(x.unit)}</small>`:''}</td><td>${esc(x.category)}</td><td>${esc(x.status)}</td><td>${esc(x.location)}</td><td><button data-action="detail" data-id="${x.id}">Vis</button></td></tr>`).join('')}</tbody></table>${items.length?'':'<p class="empty">Ingen utstyr funnet.</p>'}</div>`}
function itemCards(items){return `<div class="cards">${items.map(x=>`<article class="tile"><div class="gallery-placeholder" aria-hidden="true">Syntetisk eksempel</div><p class="eyebrow">${esc(x.category)} · ${esc(x.status)}</p><a href="#item-${x.id}" data-action="detail" data-id="${x.id}"><strong>${esc(x.name)}</strong></a><p>Plassering: ${esc(x.location)}</p>${x.sku?`<small>${esc(x.sku)}</small>`:''}<button data-action="detail" data-id="${x.id}">Vis</button></article>`).join('')||'<p class="empty">Ingen utstyr funnet.</p>'}</div>`}
function itemView(){let rows=db.items.filter(x=>`${x.name} ${x.sku}`.toLocaleLowerCase('nb').includes(itemQuery));
 const fcat=document.querySelector('#filter-category')?.value||'Alle kategorier',fst=document.querySelector('#filter-status')?.value||'Alle statuser',floc=document.querySelector('#filter-location')?.value||'Alle plasseringer',frun=document.querySelector('#filter-run')?.value||'Alle løp';
 rows=rows.filter(x=>(fcat==='Alle kategorier'||x.category===fcat)&&(fst==='Alle statuser'||x.status===fst)&&(floc==='Alle plasseringer'||x.location===floc)&&(frun==='Alle løp'||x.runs.includes(frun)));

 let content='';if(groupBy==='none')content=layout==='table'?tableRows(rows):itemCards(rows);else{const groups={};rows.forEach(x=>{const labels=groupBy==='Løp'?(x.runs.length?x.runs:['Uten løp']):[x[groupBy==='Kategori'?'category':groupBy==='Status'?'status':'location']||'Uten plassering'];labels.forEach(k=>(groups[k]??=[]).push(x))});content=Object.entries(groups).map(([g,arr])=>`<section class="panel"><h3>${esc(g)}</h3>${layout==='table'?tableRows(arr):itemCards(arr)}</section>`).join('')||'<p class="empty">Ingen utstyr funnet.</p>'}
 return `<section class="panel"><div class="filterbar"><h2>Søk og filter</h2><label>Søk<input id="item-search" type="search" value="${esc(itemQuery)}" placeholder="Søk..."></label><label>Kategori<select id="filter-category"><option>Alle kategorier</option>${opts(db.categories,fcat)}</select></label><label>Status<select id="filter-status"><option>Alle statuser</option>${opts(db.statuses,fst)}</select></label><label>Plassering<select id="filter-location"><option>Alle plasseringer</option>${opts(db.locations,floc)}</select></label><label>Løp<select id="filter-run"><option>Alle løp</option>${opts(db.runs,frun)}</select></label><label>Grupper<select id="group-by"><option value="none" ${groupBy==='none'?'selected':''}>Ingen gruppering</option>${['Kategori','Status','Plassering','Løp'].map(x=>`<option ${groupBy===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="row-actions"><button data-action="reset-filters">Nullstill</button><button class="${layout==='table'?'primary':''}" data-action="layout-table">Tabell</button><button class="${layout==='gallery'?'primary':''}" data-action="layout-gallery">Galleri</button><button class="primary" data-action="add-item">+ Legg til</button></div></div><p class="muted">${rows.length} treff · Merk: ved gruppering på løp kan utstyr vises i flere grupper.</p></section>
 <section class="panel">${content}</section>${detailId?itemDetail(detailId):''}`}
function itemDetail(itemId){const x=getItem(itemId);if(!x)return'';const instances=db.instances.filter(u=>u.itemId===itemId),attachments=db.attachments.filter(a=>a.itemId===itemId),notes=db.notes.filter(n=>n.itemId===itemId&&!n.kind),history=db.notes.filter(n=>n.itemId===itemId&&n.kind==='audit'),runs=Array.isArray(x.runs)?x.runs:[];
 return `<section class="panel detail" id="item-detail"><div class="detail-head"><div><p class="eyebrow">VAREDETALJ</p><h2>${esc(x.name)}</h2><span>${esc(x.sku)}</span></div><button data-action="close-detail">Tilbake</button></div><div class="detail-grid"><div class="detail-main"><section class="subpanel"><h3>Enheter (serienummer)</h3><button data-action="add-instance" data-item="${x.id}">+ Legg til enhet</button>${instances.length?`<div class="table-wrap"><table><thead><tr><th>Serienr.</th><th>Status</th><th>Plassering</th><th>Tilstandsnotat</th><th></th></tr></thead><tbody>${instances.map(u=>`<tr><td>${esc(u.serial)}</td><td>${esc(u.status)}</td><td>${esc(u.location)}</td><td>${esc(u.condition||'')}</td><td><button data-action="detail-instance" data-id="${u.id}">Vis</button> <button data-action="edit-instance" data-id="${u.id}">Rediger</button> <button data-action="delete-instance" data-id="${u.id}">Slett</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Ingen enheter registrert.</p>'}${unitDetailId?instanceDetail(unitDetailId):''}</section>
 <section class="subpanel"><h3>Vedlegg</h3><p class="muted">Demoen modellerer dokumentetiketter og kategorier; ingen fil eller media lastes opp.</p><button data-action="add-attachment" data-item="${x.id}">+ Last opp vedlegg</button>${attachments.map(a=>`<div class="list-row"><span>${esc(a.label)} · ${esc(a.category)}</span><span class="row-actions"><button data-action="view-attachment" data-id="${a.id}">Vis</button><button data-action="delete-attachment" data-id="${a.id}">Slett</button></span></div>`).join('')||'<p>Ingen vedlegg.</p>'}</section>
 <section class="subpanel"><h3>Instruks</h3><p>${esc(x.note||'Ingen instruks registrert.')}</p><button data-action="edit-instructions" data-id="${x.id}">Rediger instruks</button></section>
 <section class="subpanel"><h3>Notater</h3><button data-action="add-note" data-item="${x.id}">+ Legg til notat</button>${notes.map(n=>`<div class="list-row"><span>${esc(n.text)} <small>${esc(n.date)}</small></span><button data-action="delete-note" data-id="${n.id}">Slett</button></div>`).join('')||'<p>Ingen notater.</p>'}</section>
 <section class="subpanel"><h3>Historikk</h3>${history.map(n=>`<p class="history-row"><time>${esc(n.date)}</time> · ${esc(n.text)}</p>`).join('')||'<p>Ingen historikk registrert.</p>'}</section></div>
 <aside class="detail-sidebar"><div class="subpanel"><h3>Informasjon</h3><dl><dt>Kategori</dt><dd>${esc(x.category)}</dd><dt>Status</dt><dd>${esc(x.status)}</dd><dt>Plassering</dt><dd>${esc(x.location)}</dd><dt>Antall</dt><dd>${x.qty} ${esc(x.unit)}</dd><dt>Løp</dt><dd>${runs.map(esc).join(', ')||'Uten løp'}</dd></dl></div><div class="subpanel"><h3>Lager / Verdi</h3><dl><dt>Innkjøpspris</dt><dd>${money(x.cost)}</dd><dt>Estimert verdi</dt><dd>${money(x.value)}</dd><dt>Total innkjøp</dt><dd>${money(x.qty*x.cost)}</dd><dt>Total estimert</dt><dd>${money(x.qty*x.value)}</dd></dl></div><div class="subpanel"><h3>Egenskaper</h3><p>Størrelse: ${esc(x.size||'--')} · Vekt (gram): ${Number(x.weight)||'--'}</p>${Object.entries(x.meta||{}).map(([k,v])=>`<p>${esc(db.metaFields.find(m=>m.key===k)?.label||k)}: ${esc(v)}</p>`).join('')}<button data-action="edit-meta" data-id="${x.id}">Rediger egenskaper</button></div></aside></div></section>`}
function instanceDetail(unitId){const u=db.instances.find(v=>v.id===unitId);if(!u)return'';const item=getItem(u.itemId),files=db.attachments.filter(a=>a.instanceId===u.id),notes=db.notes.filter(n=>n.instanceId===u.id&&!n.kind),history=db.notes.filter(n=>n.instanceId===u.id&&n.kind==='audit');return `<article class="instance-detail"><div class="detail-head"><h4>Enhet ${esc(u.serial)}</h4><button data-action="close-instance-detail">Tilbake</button></div><p><strong>Enhet tilhører:</strong> ${esc(item?.name||'--')} · ${esc(item?.sku||'')}</p><p><strong>Status:</strong> ${esc(u.status)} · <strong>Plassering:</strong> ${esc(u.location)}</p><p><strong>Tilstand:</strong> ${esc(u.condition||'--')}</p><button data-action="add-instance-attachment" data-id="${u.id}">Legg til vedlegg</button> <button data-action="add-instance-note" data-id="${u.id}">Legg til notat</button><h5>Vedlegg</h5>${files.map(f=>`<p>${esc(f.label)} · ${esc(f.category)} <button data-action="view-attachment" data-id="${f.id}">Vis</button> <button data-action="delete-attachment" data-id="${f.id}">Slett</button></p>`).join('')||'<p>Ingen vedlegg.</p>'}<h5>Notater</h5>${notes.map(n=>`<p>${esc(n.text)} · ${esc(n.date)} <button data-action="delete-note" data-id="${n.id}">Slett</button></p>`).join('')||'<p>Ingen notater.</p>'}<h5>Historikk</h5>${history.map(n=>`<p>${esc(n.date)} · ${esc(n.text)}</p>`).join('')||'<p>Ingen historikk registrert.</p>'}</article>`}
function contactsView(){if(contactDetailId){const c=db.contacts.find(v=>v.id===contactDetailId);if(c)return contactDetail(c)}return `<section class="panel"><div class="section-head"><div><h2>Leietakere</h2><p>Kontaktopplysninger er tydelig syntetiske og finnes bare i fanens minne.</p></div><button class="primary" data-action="add-contact">+ Legg til leietaker</button></div><div class="table-wrap"><table><thead><tr><th>Navn</th><th>E-post</th><th>Telefon</th><th>Handlinger</th></tr></thead><tbody>${db.contacts.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.email||'--')}</td><td>${esc(c.phone||'--')}</td><td><div class="row-actions"><button data-action="view-contact" data-id="${c.id}">Vis</button>${c.email?`<a href="mailto:${encodeURIComponent(c.email)}">E-post</a>`:''}<button data-action="edit-contact" data-id="${c.id}">Rediger</button></div></td></tr>`).join('')||'<tr><td colspan="4">Ingen leietakere registrert.</td></tr>'}</tbody></table></div></section>`}
function contactDetail(c){const history=db.rentals.filter(r=>r.contactId===c.id),notes=db.contactNotes.filter(n=>n.contactId===c.id);return `<section class="panel detail"><div class="detail-head"><div><p class="eyebrow">LEIETAKER</p><h2>${esc(c.name)}</h2></div><button data-action="close-contact">Tilbake</button></div><dl><dt>E-post</dt><dd>${esc(c.email||'--')}</dd><dt>Telefon</dt><dd>${esc(c.phone||'--')}</dd><dt>Organisasjonsnummer</dt><dd>${esc(c.org_number||'--')}</dd><dt>Adresse</dt><dd>${esc(c.address||'--')}</dd><dt>Notat</dt><dd>${esc(c.note||'--')}</dd></dl><h3>Utleiehistorikk</h3>${history.map(r=>`<p>Avtale ${esc(r.id)} · ${esc(r.status)} · ${esc(r.start)} – ${esc(r.end)}</p>`).join('')||'<p>Ingen utleiehistorikk.</p>'}<h3>Notater</h3><button data-action="add-contact-note" data-id="${c.id}">+ Legg til notat</button>${notes.map(n=>`<p>${esc(n.text)} <small>${esc(n.author)} · ${esc(n.date)}</small></p>`).join('')||'<p>Ingen notater.</p>'}</section>`}
function rentalLineText(r){return r.lines.map(l=>`${getItem(l.itemId)?.name||'Utstyr'} × ${l.qty}${l.instanceIds?.length?` (${l.instanceIds.length} serienummerenheter)`:''}`).join(', ')}
function rentalView(){if(rentalSub==='leietakere')return contactsView();const rows=db.rentals.filter(r=>rentalSub==='historikk'?r.status==='Returnert':rentalSub==='avtaler'?r.status!=='Returnert':true);return `<section class="panel"><div class="row-actions subnav"><button data-rental-sub="avtaler" class="${rentalSub==='avtaler'?'primary':''}">Utleieavtaler</button><button data-rental-sub="leietakere" class="${rentalSub==='leietakere'?'primary':''}">Leietakere</button><button data-rental-sub="historikk" class="${rentalSub==='historikk'?'primary':''}">Utleiehistorikk</button><button class="primary" data-action="new-rental">+ Ny utleieavtale</button></div><p class="muted">Utleie følger kladd → aktiv → returnert. Unike enheter flyttes til «Hos leietaker» ved aktivering; mengdevarer viser utlånt antall.</p><div class="table-wrap"><table><thead><tr><th>Avtale #</th><th>Leietaker</th><th>Status</th><th>Fra</th><th>Til</th><th>Utstyr</th><th>Handlinger</th></tr></thead><tbody>${rows.map(r=>{const c=db.contacts.find(z=>z.id===r.contactId);return `<tr><td>${esc(r.id)}</td><td>${esc(c?.name||'Slettet leietaker')}</td><td><span class="tag">${esc(r.status)}</span></td><td>${esc(r.start)}</td><td>${esc(r.end)}</td><td>${esc(rentalLineText(r))}</td><td><div class="row-actions"><button data-action="rental-detail" data-id="${r.id}">Oversikt</button>${r.status==='Kladd'?`<button data-action="activate-rental" data-id="${r.id}">Aktiver</button><button data-action="edit-rental" data-id="${r.id}">Rediger</button>`:''}${r.status==='Aktiv'?`<button data-action="return-rental" data-id="${r.id}">Registrer retur</button>`:''}</div></td></tr>`}).join('')||'<tr><td colspan="7">Ingen avtaler funnet.</td></tr>'}</tbody></table></div>${rentalDetailId?rentalDetailPanel(db.rentals.find(r=>r.id===rentalDetailId)):''}${wizard?wizardView():''}</section>`}
function rentalDetailPanel(r){if(!r)return'';const days=Math.max(1,Math.ceil((new Date(r.end)-new Date(r.start))/86400000)+1);return `<section class="subpanel"><div class="detail-head"><div><p class="eyebrow">AVTALE ${esc(r.id)}</p><h3>Oversikt · ${esc(r.status)}</h3></div><button data-action="close-rental-detail">Tilbake</button></div><p>${esc(db.contacts.find(c=>c.id===r.contactId)?.name||'--')} · ${esc(r.start)} – ${esc(r.end)} · ${days} dager · ${money(r.rate*days)} syntetisk estimat</p><label>Notat<textarea id="rental-note">${esc(r.note||'')}</textarea></label><button data-action="save-rental-note" data-id="${r.id}">Lagre notat</button><h4>Legg til utstyr i avtale</h4>${r.status==='Kladd'?`<div class="form-grid"><label>Utstyr<select id="rental-item-${r.id}">${db.items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)} · ${availableQty(i)} tilgjengelig</option>`).join('')}</select></label><label>Antall<input id="rental-qty-${r.id}" type="number" min="1" value="1"></label><label>Unike enheter<select id="rental-units-${r.id}" multiple>${db.instances.filter(u=>u.status!=='Utleid / utlånt').map(u=>`<option value="${esc(u.id)}">${esc(u.serial)} · ${esc(getItem(u.itemId)?.name)}</option>`).join('')}</select></label><button data-action="add-rental-line" data-id="${r.id}">Legg til utstyr i avtale</button></div>`:'<p>Utstyrslinjer kan endres mens avtalen er kladd.</p>'}<ul>${r.lines.map((l,index)=>`<li>${esc(getItem(l.itemId)?.name||'Slettet utstyr')} × ${l.qty}${l.instanceIds?.length?` · ${l.instanceIds.map(uid=>esc(db.instances.find(u=>u.id===uid)?.serial)).join(', ')}`:''}${r.status==='Kladd'?` <button data-action="remove-rental-line" data-id="${r.id}" data-index="${index}">Fjern linje</button>`:''}</li>`).join('')||'<li>Ingen utstyr lagt til.</li>'}</ul></section>`}
function wizardView(){const step=wizard.step;return `<section class="wizard"><p class="eyebrow">NY UTLEIEAVTALE · TRINN ${step} AV 3</p><div class="wizard-steps"><span class="${step>=1?'current':''}">1. Leietaker og periode</span><span class="${step>=2?'current':''}">2. Legg til utstyr i avtale</span><span class="${step>=3?'current':''}">3. Oversikt</span></div>${step===1?`<div class="form-grid"><label>Leietaker<select id="wizard-contact">${db.contacts.map(c=>`<option value="${esc(c.id)}" ${c.id===wizard.contactId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Startdato (AAAA-MM-DD)<input id="wizard-start" type="date" value="${esc(wizard.start)}"></label><label>Sluttdato (AAAA-MM-DD)<input id="wizard-end" type="date" value="${esc(wizard.end)}"></label><label>Døgnpris (kr)<input id="wizard-rate" type="number" min="0" value="${wizard.rate}"></label><button data-action="wizard-next">Neste</button></div>`:step===2?`<div class="form-grid"><label>Utstyr<select id="wizard-item">${db.items.map(i=>`<option value="${esc(i.id)}" ${i.id===wizard.itemId?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><label>Antall<input id="wizard-qty" type="number" min="1" value="${wizard.qty||1}"></label><label>Unike enheter<select id="wizard-units" multiple>${db.instances.map(u=>`<option value="${u.id}" ${wizard.lines.some(l=>l.instanceIds.includes(u.id))?'selected':''}>${esc(u.serial)} · ${esc(getItem(u.itemId)?.name)}</option>`).join('')}</select></label><button data-action="wizard-add-line">Legg til utstyr i avtale</button></div><ul>${wizard.lines.map(l=>`<li>${esc(getItem(l.itemId)?.name)} × ${l.qty} ${l.instanceIds.length?`· ${l.instanceIds.map(u=>esc(db.instances.find(x=>x.id===u)?.serial)).join(', ')}`:''} <button data-action="wizard-remove-line" data-id="${l.localId}">Fjern</button></li>`).join('')}</ul><div class="row-actions"><button data-action="wizard-back">Tilbake</button><button data-action="wizard-next">Neste</button></div>`:`<h3>Oversikt</h3><dl><dt>Leietaker</dt><dd>${esc(db.contacts.find(c=>c.id===wizard.contactId)?.name||'--')}</dd><dt>Periode</dt><dd>${esc(wizard.start)} – ${esc(wizard.end)}</dd><dt>Utstyr</dt><dd>${esc(wizard.lines.map(l=>`${getItem(l.itemId)?.name} × ${l.qty}`).join(', '))}</dd><dt>Leiepris</dt><dd>${money(wizard.rate)} per døgn · syntetisk eksempel</dd></dl><div class="row-actions"><button data-action="wizard-back">Tilbake</button><button class="primary" data-action="wizard-create">Opprett avtale (kladd)</button></div>`}</section>`}
function reportsView(){if(reportSub==='lageropptelling')return countsView();const totalQty=db.items.reduce((a,x)=>a+x.qty,0),purchase=db.items.reduce((a,x)=>a+x.cost,0),estimate=db.items.reduce((a,x)=>a+x.value,0);return `<section class="panel"><div class="row-actions subnav"><button data-report-sub="oversikt" class="${reportSub==='oversikt'?'primary':''}">Oversikt</button><button data-report-sub="lageropptelling" class="${reportSub==='lageropptelling'?'primary':''}">Lageropptelling</button></div><h2>Rapporter</h2><section class="summary"><div class="metric"><span>Varetyper</span><strong>${db.items.length}</strong></div><div class="metric"><span>Totalt antall</span><strong>${totalQty}</strong></div><div class="metric"><span>Total innkjopspris</span><strong>${money(purchase)}</strong></div><div class="metric"><span>Total estimert verdi</span><strong>${money(estimate)}</strong></div></section><h3>Aktive utleier</h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Leietaker</th><th>Fra</th><th>Til</th></tr></thead><tbody>${activeRentals().map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(db.contacts.find(c=>c.id===r.contactId)?.name||'--')}</td><td>${esc(r.start)}</td><td>${esc(r.end)}</td></tr>`).join('')||'<tr><td colspan="4">Ingen aktive utleier.</td></tr>'}</tbody></table></div><button data-tab-action="import">Gå til eksport</button></section>`}
function sharesView(){return `<section class="panel"><h2>Delte lister</h2><p>Kilden støtter lesetilgang via «magisk lenke» og valgfri utløpsdato (standard 30 dager). Her opprettes en listeoppføring for demonstrasjon bare i denne fanen. Ingen ekte URL, token eller ekstern tilgang blir opprettet.</p><div class="form-grid"><label>Kategori<select id="share-category"><option>Alle kategorier</option>${opts(db.categories,db.shareFilters.category)}</select></label><label>Status<select id="share-status"><option>Alle statuser</option>${opts(db.statuses,db.shareFilters.status)}</select></label><label>Utløper etter<select id="share-days"><option>7</option><option selected>30</option><option>90</option></select> dager (eksempel)</label><button data-action="share-preview">Forhåndsvis delt leseliste</button><button data-action="create-share">Opprett demooppføring</button></div><div id="share-preview">${db.shareFilters.preview?`<h3>Forhåndsvisning · syntetisk eksempel</h3>${tableRows(db.items.filter(i=>(db.shareFilters.category==='Alle kategorier'||i.category===db.shareFilters.category)&&(db.shareFilters.status==='Alle statuser'||i.status===db.shareFilters.status)))}`:''}</div><h3>Delte listeoppføringer · kun lokal demonstrasjon</h3>${db.shares.map(s=>`<div class="list-row"><span>${esc(s.label)} · ${esc(s.category)} · ${esc(s.status)} · utløper ${esc(s.expires)} · ingen faktisk lenke</span><button data-action="revoke-share" data-id="${s.id}">Slett</button></div>`).join('')||'<p>Ingen delte lister registrert.</p>'}</section>`}
function importView(){return `<section class="panel"><h2>Import/eksport</h2><p>Importer kun syntetisk varedata. Valgt CSV-fil leses lokalt i nettleseren, brukes bare i fanens minne og sendes ikke noe sted.</p><div class="tiles"><article class="tile"><h3>Import-mal</h3><p>Last ned malen, fyll inn syntetiske data og importer CSV-filen nedenfor.</p><button data-action="template">Last ned import-mal (CSV)</button><label>Importer CSV<input id="csv-file" type="file" accept=".csv,text/csv"></label><button data-action="import-csv">Importer syntetiske rader</button><div id="import-result" role="status"></div></article><article class="tile"><h3>Eksport</h3><p>Eksporter varer eller et markert utvalg som Excel-arbeidsbok lokalt.</p><button data-action="export-all">Eksporter alle varer (XLSX)</button><div id="export-result" role="status"></div></article></div><h3>CSV-felt</h3><code>sku,name,category,unit,qty,cost,value,location,status,size,weight_grams</code></section>`}
function countsView(){return `<section class="panel"><h2>Lageropptelling</h2>${db.items.map(x=>`<details class="setting"><summary>${esc(x.name)} · ${esc(x.sku)} — Nåværende: ${x.qty}</summary><div class="form-grid"><label>Type<select data-count-type="${x.id}"><option value="opptelling">Opptelling (absolutt antall)</option><option value="justering">Justering (+/- delta)</option></select></label><label>Nytt antall (opptelling)<input data-count-value="${x.id}" type="number" min="0" value="${x.qty}"></label><label>Delta (justering)<input data-count-delta="${x.id}" type="number" value="0"></label><label>Årsak *<input data-count-reason="${x.id}" required value=""></label><button data-action="count-adjust" data-id="${x.id}">Lagre</button></div></details>`).join('')||'<p>Ingen utstyr i lageret.</p>'}</section>`}
const configSets={Kategorier:'categories',Plasseringer:'locations',Statuser:'statuses',Løp:'runs','Vedleggskategorier':'attachmentCategories'};
function settingsSection(title,key,copy){const rows=db[key];return `<details class="setting"><summary>${title}<span class="count">${rows.length}</span><small class="preview">${esc(rows.slice(0,3).join(' · '))}</small></summary><p>${copy}</p><ul class="config-list">${rows.map((v,i)=>`<li><span>${esc(v)}</span><span class="row-actions"><button data-action="edit-config" data-set="${key}" data-index="${i}">Rediger</button><button data-action="delete-config" data-set="${key}" data-index="${i}" ${(['Tilgjengelig','Hovedlager'].includes(v))?'disabled title="Systemverdi kan ikke slettes"':''}>Slett</button></span></li>`).join('')}</ul><button data-action="add-config" data-set="${key}">+ Ny ${title.toLocaleLowerCase('nb')}</button></details>`}
function settingsView(){return `<section class="panel"><h2>Innstillinger</h2><p>Konfigurer kategorier, plasseringer, statuser og andre basisinnstillinger for lageret. Åpne en seksjon for å legge til, redigere eller slette.</p><details class="setting" ${db.configDone?'':'open'}><summary>Førstegangsoppsett</summary><p>Veiviseren hjelper med kategorier, plasseringer, statuser, KATKODE for SKU og dokumentkategorier.</p><ol><li>Opprett eller bekreft kategorier</li><li>Opprett lagerplasseringer</li><li>Velg standardstatuser</li><li>Angi SKU-kategori og vedleggskategorier</li></ol><button data-action="setup">${db.configDone?'Kjør oppsettveiviser på nytt':'Start oppsettveiviser'}</button></details><div class="settings-grid">${settingsSection('Kategorier','categories','Kategorier brukes til å sortere og filtrere utstyr. Hvert utstyr tilhører én kategori.')}${settingsSection('Plasseringer','locations','Plasseringer angir hvor utstyr befinner seg, f.eks. et lager eller en hylle. Systemplasseringer kan ikke slettes.')}${settingsSection('Statuser','statuses','Statuser viser tilstanden til utstyr, f.eks. tilgjengelig, utleid eller til reparasjon. Systemstatuser kan ikke slettes.')}${settingsSection('Løp','runs','Løp grupperer utstyr etter arrangement eller sesong. Hvert utstyr kan tilhøre ett eller flere løp.')}${settingsSection('Vedleggskategorier','attachmentCategories','Vedleggskategorier hjelper deg å sortere dokumenter og bilder som er lastet opp til utstyr.')}</div><details class="setting"><summary>Egendefinerte felt <span class="count">${db.metaFields.length}</span><small class="preview">${esc(db.metaFields.slice(0,3).map(m=>m.label).join(' · '))}</small></summary><p>Legg til egne felt som vises på hvert utstyr, f.eks. vekt, størrelse eller tekniske spesifikasjoner.</p><div class="table-wrap"><table><thead><tr><th>Nøkkel</th><th>Etikett</th><th>Type</th><th>Enhet</th><th>Aktiv</th><th>Rekkefølge</th><th></th></tr></thead><tbody>${db.metaFields.map((m,i)=>`<tr><td>${esc(m.key)}</td><td>${esc(m.label)}</td><td>${esc(m.type)}</td><td>${esc(m.unit)}</td><td>${m.active?'Ja':'Nei'}</td><td>${m.order}</td><td><button data-action="edit-meta-field" data-index="${i}">Rediger</button> <button data-action="delete-meta-field" data-index="${i}">Slett</button></td></tr>`).join('')||'<tr><td colspan="7">Ingen egendefinerte felt registrert.</td></tr>'}</tbody></table></div><button data-action="add-meta-field">+ Legg til felt</button></details></section>`}
function render(){document.querySelector('#view').innerHTML=notice?`<p class="notice" role="status">${esc(notice)}</p>${renderCurrent()}`:renderCurrent()}
function renderCurrent(){if(currentTab==='varer')return itemView();if(currentTab==='utleie')return rentalView();if(currentTab==='rapporter')return reportsView();if(currentTab==='delte')return sharesView();if(currentTab==='import')return importView();return settingsView()}
function itemForm(item){const x=item||{name:'',sku:'',category:db.categories[0],unit:'stk',qty:0,cost:0,value:0,location:db.locations[0],status:db.statuses[0],note:''};openEditor(item?'Rediger utstyr':'Legg til utstyr',[
 field('name','Navn *',x.name,'text',{required:true}),field('sku','SKU',x.sku),field('unit','Enhet',x.unit||'stk'),field('qty','Antall',x.qty,'number',{min:0}),field('cost','Innkjopspris (kr)',x.cost,'number',{step:'any'}),field('value','Estimert verdi (kr)',x.value,'number',{step:'any'}),field('category','Kategori',x.category,'select',{options:db.categories}),field('location','Plassering',x.location,'select',{options:db.locations}),field('status','Status',x.status,'select',{options:db.statuses}),field('note','Instruks',x.note,'textarea')
 ],d=>{const data={name:d.name.trim(),sku:d.sku.trim(),category:d.category,unit:d.unit||'stk',qty:Number(d.qty||0),cost:Number(d.cost||0),value:Number(d.value||0),location:d.location,status:d.status,note:d.note||''};if(item){Object.assign(item,data);log(item.id,'utstyr oppdatert')}else{if(data.sku&&db.items.some(i=>i.sku.toLowerCase()===data.sku.toLowerCase())){notice='SKU finnes allerede. Bruk en unik syntetisk SKU.';return}const added={id:id(),...data,size:'',weight:null,runs:[],meta:{},rentedQty:0};db.items.push(added);log(added.id,'utstyr opprettet')}})}
function doCount(x,value,reason){const qty=Math.max(0,Number(value)||0),delta=qty-x.qty;if(delta===0){notice='Opptalt antall stemmer.';return}x.qty=qty;log(x.id,`lageropptelling ${delta>0?'+':''}${delta} stk · ${reason||'syntetisk årsak'}`);notice=`Opptelling registrert i fanen: avvik ${delta>0?'+':''}${delta} stk.`}
function downloadCsv(name,rows){const csv=rows.map(r=>r.map(v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+@\-]/.test(s))s=`'${s}`;return `"${s.replaceAll('"','""')}"`}).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0)}
function csvRows(items){return [['sku','name','category','unit','qty','cost','value','location','status','size','weight_grams'],...items.map(x=>[x.sku,x.name,x.category,x.unit,x.qty,x.cost,x.value,x.location,x.status,x.size,x.weight])]}
function downloadXlsx(name,rows){const enc=new TextEncoder(),proto='http'+':'+String.fromCharCode(47,47),files={'[Content_Types].xml':`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="${proto}schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`,'_rels/.rels':`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="${proto}schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${proto}schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,'xl/workbook.xml':`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="${proto}schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="${proto}schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Utstyr" sheetId="1" r:id="rId1"/></sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="${proto}schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${proto}schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`};
 const xml=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&apos;'),col=n=>{let out='';for(n++;n;n=Math.floor((n-1)/26))out=String.fromCharCode(65+(n-1)%26)+out;return out};
 const sheet=rows.map((row,ri)=>`<row r="${ri+1}">${row.map((v,ci)=>typeof v==='number'?`<c r="${col(ci)}${ri+1}" t="n"><v>${Number.isFinite(v)?v:0}</v></c>`:`<c r="${col(ci)}${ri+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')}</row>`).join('');files['xl/worksheets/sheet1.xml']=`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="${proto}schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheet}</sheetData></worksheet>`;
 const table=Uint32Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});const crc=data=>{let c=0xffffffff;for(const b of data)c=table[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0};const chunks=[],central=[];let offset=0;
 for(const [filename,contents] of Object.entries(files)){const nb=enc.encode(filename),data=enc.encode(contents),sum=crc(data),local=new Uint8Array(30+nb.length+data.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,sum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,nb.length,true);local.set(nb,30);local.set(data,30+nb.length);chunks.push(local);const cd=new Uint8Array(46+nb.length),d=new DataView(cd.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint32(16,sum,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,nb.length,true);d.setUint32(42,offset,true);cd.set(nb,46);central.push(cd);offset+=local.length}
 const centralBytes=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,central.length,true);ev.setUint16(10,central.length,true);ev.setUint32(12,centralBytes,true);ev.setUint32(16,offset,true);const blob=new Blob([...chunks,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0)}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted&&c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function commitRental(r){if(r.status!=='Kladd')return;for(const line of r.lines){const it=getItem(line.itemId);if(!it)continue;if(line.instanceIds?.length){for(const unitId of line.instanceIds){const u=db.instances.find(v=>v.id===unitId);if(u){u.previousLocation=u.location;u.previousStatus=u.status;u.location=`Hos leietaker: ${db.contacts.find(c=>c.id===r.contactId)?.name||'Syntetisk leietaker'}`;u.status='Utleid / utlånt'}}}else{if(it.rentedQty===0)it._statusBeforeRental=it.status;it.rentedQty=Math.min(it.qty,it.rentedQty+line.qty);it.status='Utleid / utlånt'}log(it.id,`utleieavtale ${r.id} aktivert`)}r.status='Aktiv';notice=`Avtale ${r.id} aktivert i denne fanen.`}
function returnRental(r){if(r.status!=='Aktiv')return;for(const line of r.lines){const it=getItem(line.itemId);if(!it)continue;if(line.instanceIds?.length){for(const unitId of line.instanceIds){const u=db.instances.find(v=>v.id===unitId);if(u){u.location=u.previousLocation||it.location;u.status=u.previousStatus||'Tilgjengelig';delete u.previousLocation;delete u.previousStatus}}}else{it.rentedQty=Math.max(0,it.rentedQty-line.qty);if(it.rentedQty===0){it.status=it._statusBeforeRental||'Tilgjengelig';delete it._statusBeforeRental}}log(it.id,`utleieavtale ${r.id} returnert`)}r.status='Returnert';notice=`Retur for avtale ${r.id} registrert i denne fanen.`}
