view.addEventListener('click',action);
view.addEventListener('input',e=>{if(e.target.id==='item-search'){itemQuery=e.target.value;const position=e.target.selectionStart;render();const n=document.querySelector('#item-search');n?.focus();n?.setSelectionRange(position,position)}});
view.addEventListener('change',e=>{if(e.target.id==='group-by'){groupBy=e.target.value;render()}else if(e.target.id==='csv-file'){document.querySelector('#import-result').textContent=e.target.files[0]?`${e.target.files[0].name} valgt lokalt.`:''}else if(e.target.matches('#filter-category,#filter-status,#filter-location,#filter-run'))render()});
const editorForm=document.querySelector('#editor-form');editorForm.addEventListener('submit',(e)=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;f._demoSave?.(Object.fromEntries(new FormData(f)));document.querySelector('#editor-dialog').close();render()});
render();
